-- ТОЛЬКО ОТВЕТЫ ЛУИЗЫ. Выполнять после файла заданий, не давать доступ соискателям.
BEGIN;
CREATE TABLE IF NOT EXISTS hackathon_task_answer_keys (task_id TEXT PRIMARY KEY REFERENCES hackathon_tasks_public(id) ON DELETE CASCADE, answer TEXT, explanation TEXT, reference_solution TEXT, criteria TEXT, max_score INTEGER NOT NULL);
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-JR-T01', 'Они обозначают назначение и структуру содержимого. Это облегчает навигацию вспомогательными технологиями и поддержку кода. Для действия используют <button>, а не элемент, выбранный только из-за внешнего вида.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-JR-T02', 'Content, padding, border и margin. При box-sizing: border-box заданная width включает content, padding и border; margin остаётся снаружи.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-JR-T03', 'Обе переменные имеют блочную область видимости. let можно переназначить; const нельзя переназначить после объявления. const не делает вложенные свойства объекта неизменяемыми.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-JR-T04', 'При всплытии событие после целевого элемента проходит к его предкам. В обработчике event.stopPropagation() прекращает дальнейшее распространение; применять его следует только при необходимости.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-JR-T05', 'Использовать try/catch и отдельно проверить response.ok. fetch обычно не отклоняет Promise для HTTP-ответов 404 или 500, поэтому статус нужно обработать явно; сетевые сбои приводят к исключению.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-JR-A01', 'includes сравнивает регистр символов, а query может содержать пробелы по краям. Например, «Alpha» не совпадёт с «alpha». Исправление: const normalizedQuery = query.trim().toLocaleLowerCase(); const visible = items.filter(item => item.name.toLocaleLowerCase().includes(normalizedQuery)); Пустой запрос после trim даст все элементы, поскольку пустая строка входит в любую строку.', 'includes сравнивает регистр символов, а query может содержать пробелы по краям. Например, «Alpha» не совпадёт с «alpha». Исправление: const normalizedQuery = query.trim().toLocaleLowerCase(); const visible = items.filter(item => item.name.toLocaleLowerCase().includes(normalizedQuery)); Пустой запрос после trim даст все элементы, поскольку пустая строка входит в любую строку.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-JR-A02', 'Браузер интерпретирует строку как HTML. Если данные недоверенные, это может привести к внедрению разметки и скриптов. Создайте элемент и присвойте listItem.textContent = item.name, затем добавьте его через append. textContent отображает значение как текст, а не как HTML.', 'Браузер интерпретирует строку как HTML. Если данные недоверенные, это может привести к внедрению разметки и скриптов. Создайте элемент и присвойте listItem.textContent = item.name, затем добавьте его через append. textContent отображает значение как текст, а не как HTML.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-JR-P01', NULL, NULL, 'const render = () => {
  const query = input.value.trim().toLocaleLowerCase();
  const filtered = people.filter(person =>
    `${person.name} ${person.role}`.toLocaleLowerCase().includes(query)
  );
  results.replaceChildren();
  for (const person of filtered) {
    const li = document.createElement("li");
    li.textContent = `${person.name} — ${person.role}`;
    results.append(li);
  }
  empty.hidden = filtered.length !== 0;
};
input.addEventListener("input", render);
render();', 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-MD-T01', 'React и инструменты вокруг него опираются на сравнение ссылок для обнаружения изменений и оптимизации. Мутация сохраняет прежнюю ссылку и может не вызвать ожидаемый рендер; иммутабельное обновление создаёт новые ссылки на изменённых уровнях структуры.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-MD-T02', 'Массив описывает реактивные значения, от которых зависит синхронизация с внешней системой. Эффект повторно запускается при изменении зависимостей; нужно включать все используемые значения компонента, соблюдая правила React Hooks, а не подавлять предупреждения без обоснования.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-MD-T03', 'key помогает React сопоставить элементы между рендерами. Индекс меняется при вставке, удалении или перестановке и может привести к переносу состояния или DOM-содержимого не тому элементу. Предпочтителен устойчивый уникальный идентификатор данных.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-MD-T04', 'Это объединение вариантов объектов с общим дискриминантным полем-литералом, например status: "loading" | "success" | "error". Проверка status сужает тип и позволяет типобезопасно обращаться к полям соответствующего варианта.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-MD-T05', 'Поле должно иметь программно связанную метку, быть доступно с клавиатуры и сохранять видимый индикатор фокуса. Кнопка должна иметь понятное имя и быть настоящим button. Изменение результатов и ошибки следует объявлять уместно и ненавязчиво, например через область aria-live; не следует без необходимости озвучивать каждый ввод символа.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-MD-A01', 'query используется, но отсутствует в зависимостях, поэтому эффект выполняется при монтировании с начальным значением и не синхронизируется с последующими изменениями. Если добавить query, быстрый последовательный ввод может привести к тому, что медленный старый ответ перезапишет новый. В исправлении зависимость включают и отменяют предыдущий запрос через AbortController; дополнительно обрабатывают ошибки и проверяют response.ok. Очистка эффекта abort-ит контроллер предыдущего запуска.', 'query используется, но отсутствует в зависимостях, поэтому эффект выполняется при монтировании с начальным значением и не синхронизируется с последующими изменениями. Если добавить query, быстрый последовательный ввод может привести к тому, что медленный старый ответ перезапишет новый. В исправлении зависимость включают и отменяют предыдущий запрос через AbortController; дополнительно обрабатывают ошибки и проверяют response.ok. Очистка эффекта abort-ит контроллер предыдущего запуска.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-MD-A02', 'После удаления индексы оставшихся элементов сдвинулись. React сопоставил прежний компонент по прежнему индексу с другим объектом и сохранил локальное состояние ввода за этой позицией. Используйте устойчивый идентификатор записи, например key={item.id}; он должен быть уникальным среди элементов списка и стабильно относиться к той же записи.', 'После удаления индексы оставшихся элементов сдвинулись. React сопоставил прежний компонент по прежнему индексу с другим объектом и сохранил локальное состояние ввода за этой позицией. Используйте устойчивый идентификатор записи, например key={item.id}; он должен быть уникальным среди элементов списка и стабильно относиться к той же записи.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-MD-P01', NULL, NULL, 'import { useEffect, useState } from "react";
type User = { id: string; name: string; role: string };
type State = { status: "idle" } | { status: "loading" } | { status: "error"; message: string } | { status: "success"; users: User[] };
export function UserSearch() {
  const [query, setQuery] = useState("");
  const [state, setState] = useState<State>({ status: "idle" });
  useEffect(() => {
    const value = query.trim();
    if (value.length < 2) { setState({ status: "idle" }); return; }
    const controller = new AbortController();
    setState({ status: "loading" });
    fetch(`/api/users?q=${encodeURIComponent(value)}`, { signal: controller.signal })
      .then(response => { if (!response.ok) throw new Error(`HTTP ${response.status}`); return response.json() as Promise<User[]>; })
      .then(users => setState({ status: "success", users }))
      .catch(error => { if (error.name !== "AbortError") setState({ status: "error", message: "Не удалось загрузить пользователей" }); });
    return () => controller.abort();
  }, [query]);
  return <section><label htmlFor="user-query">Поиск сотрудников</label><input id="user-query" value={query} onChange={event => setQuery(event.target.value)} /><div aria-live="polite">{state.status === "loading" && <p>Загрузка…</p>}{state.status === "error" && <p role="alert">{state.message}</p>}{state.status === "success" && (state.users.length ? <ul>{state.users.map(user => <li key={user.id}>{user.name} — {user.role}</li>)}</ul> : <p>Совпадений нет</p>)}</div></section>;
}', 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-SR-T01', 'Первый клиентский рендер должен соответствовать HTML, полученному с сервера. Зависимость от времени, случайных значений, различающейся локали или доступных только в браузере данных может вызвать hydration mismatch. Следует обеспечить детерминированный начальный рендер, согласовать данные и окружение и выполнять клиентские эффекты после гидратации.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-SR-T02', 'Сначала определить пользовательский симптом и измерить базовое поведение подходящими инструментами и реалистичной нагрузкой. Затем сформулировать гипотезу, изменить узкое место и повторить измерения в сопоставимых условиях. Мемоизация без подтверждённой причины может добавить сложность и не улучшить результат.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-SR-T03', 'Учитывают владельца и жизненный цикл данных, число потребителей, необходимость синхронизации, источник истины, кэширование и инвалидацию, а также стоимость сложности. Эфемерное состояние интерфейса обычно локально; серверные данные требуют стратегии загрузки и актуализации; общее хранилище оправдано при реальной потребности в совместном доступе или переходах между экранами.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-SR-T04', 'По умолчанию выводить данные как текст, избегать небезопасной вставки HTML и при необходимости использовать проверенную санитизацию. Не считать клиентскую проверку авторизацией: критические проверки должны выполняться сервером. Также учитывать безопасную обработку URL, секретов, CSP и риск межсайтовых сценариев; не хранить секреты в клиентском коде.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-SR-T05', 'Проверять чистую логику быстрыми модульными тестами, взаимодействия компонентов — интеграционными тестами через пользовательское поведение, а критические сквозные сценарии — ограниченным набором end-to-end тестов. Дополнять их проверками доступности и визуальными проверками там, где это оправдано. Тесты должны покрывать важные состояния и ошибки, а не зависеть от внутренних деталей реализации.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-SR-A01', 'Время может измениться между серверным рендером и первым клиентским рендером. Кроме того, форматирование зависит от локали и часового пояса окружения. Для согласованного HTML передавайте заранее сформированное сервером значение с определёнными настройками или рендерите стабильный placeholder с одинаковым содержимым, а локальное время обновляйте после монтирования. Простое подавление предупреждения не устраняет расхождение содержимого и должно применяться только для осознанного исключения.', 'Время может измениться между серверным рендером и первым клиентским рендером. Кроме того, форматирование зависит от локали и часового пояса окружения. Для согласованного HTML передавайте заранее сформированное сервером значение с определёнными настройками или рендерите стабильный placeholder с одинаковым содержимым, а локальное время обновляйте после монтирования. Простое подавление предупреждения не устраняет расхождение содержимого и должно применяться только для осознанного исключения.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-SR-A02', 'Сначала воспроизвести нагрузку, измерить время фильтрации, длительность рендера, частоту кадров и объём DOM в профилировщике. Разделить стоимость поиска и отображения; проверить повторную работу, объём данных и фактическую долю совпадений. Возможные меры: debounce ввода, индексирование или оптимизация поиска при подтверждённом узком месте, виртуализация списка, ограничение числа показываемых результатов, разнесение вычислений и рендера. Сравнить результат до и после на одинаковой нагрузке и проверить доступность клавиатурной навигации. Нельзя считать мемоизацию или виртуализацию автоматически полезной без измерения и проверки поведения.', 'Сначала воспроизвести нагрузку, измерить время фильтрации, длительность рендера, частоту кадров и объём DOM в профилировщике. Разделить стоимость поиска и отображения; проверить повторную работу, объём данных и фактическую долю совпадений. Возможные меры: debounce ввода, индексирование или оптимизация поиска при подтверждённом узком месте, виртуализация списка, ограничение числа показываемых результатов, разнесение вычислений и рендера. Сравнить результат до и после на одинаковой нагрузке и проверить доступность клавиатурной навигации. Нельзя считать мемоизацию или виртуализацию автоматически полезной без измерения и проверки поведения.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('FE-SR-P01', NULL, NULL, 'import { useEffect, useId, useState } from "react";
type Suggestion = { id: string; label: string };
type Result = { status: "idle" } | { status: "loading" } | { status: "error" } | { status: "success"; items: Suggestion[] };
export function Autocomplete() {
  const baseId = useId();
  const inputId = `${baseId}-input`;
  const listId = `${baseId}-list`;
  const [query, setQuery] = useState("");
  const [result, setResult] = useState<Result>({ status: "idle" });
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(-1);
  const items = result.status === "success" ? result.items : [];
  useEffect(() => {
    const value = query.trim();
    if (!value) { setResult({ status: "idle" }); setOpen(false); setActive(-1); return; }
    const controller = new AbortController();
    setResult({ status: "loading" });
    fetch(`/api/suggestions?q=${encodeURIComponent(value)}`, { signal: controller.signal })
      .then(response => { if (!response.ok) throw new Error("Request failed"); return response.json() as Promise<{ items: Suggestion[] }>; })
      .then(data => { setResult({ status: "success", items: data.items }); setOpen(true); setActive(-1); })
      .catch(error => { if (error.name !== "AbortError") { setResult({ status: "error" }); setOpen(true); setActive(-1); } });
    return () => controller.abort();
  }, [query]);
  const choose = (item: Suggestion) => { setQuery(item.label); setOpen(false); setActive(-1); };
  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Escape") { setOpen(false); setActive(-1); return; }
    if (!open || items.length === 0) return;
    if (event.key === "ArrowDown") { event.preventDefault(); setActive(index => (index + 1) % items.length); }
    if (event.key === "ArrowUp") { event.preventDefault(); setActive(index => (index - 1 + items.length) % items.length); }
    if (event.key === "Enter" && active >= 0) { event.preventDefault(); choose(items[active]); }
  };
  const activeId = active >= 0 ? `${baseId}-option-${items[active].id}` : undefined;
  return <div><label htmlFor={inputId}>Поиск подсказок</label><input id={inputId} role="combobox" aria-autocomplete="list" aria-expanded={open} aria-controls={listId} aria-activedescendant={activeId} value={query} onChange={event => { setQuery(event.target.value); setOpen(true); }} onKeyDown={onKeyDown} /><div aria-live="polite">{result.status === "loading" && <p>Загрузка</p>}{result.status === "error" && <p role="alert">Не удалось загрузить подсказки</p>}{result.status === "success" && items.length === 0 && <p>Подсказок нет</p>}</div>{open && items.length > 0 && <ul id={listId} role="listbox">{items.map((item, index) => <li id={`${baseId}-option-${item.id}`} role="option" aria-selected={index === active} key={item.id} onMouseDown={event => event.preventDefault()} onClick={() => choose(item)}>{item.label}</li>)}</ul>}</div>;
}', 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('J-FS-TH-001', 'GET предназначен для чтения ресурса и обычно не должен изменять состояние сервера; параметры фильтрации можно передать в URL. POST обычно отправляет данные для создания ресурса или выполнения операции, меняющей состояние. Список вакансий получают GET-запросом, например GET /jobs?specialization=react. Ответ GET можно кэшировать при подходящей политике, а секреты не следует помещать в URL.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('J-FS-TH-002', 'Параметры отделяют данные от SQL-команд и предотвращают SQL-инъекцию. Например: SELECT id, status FROM invitations WHERE candidate_id = ?; значение идентификатора передают отдельным параметром драйверу БД. Нельзя конкатенировать ввод в SQL-строку. Также нужны проверки корректности идентификатора и ограничение доступа к записям.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('J-FS-TH-003', 'Состояние хранит меняющиеся данные, от которых зависит отображение, например статус приглашения. Данные можно загрузить в эффекте при изменении идентификатора, сохранить через useState и вывести условно. Следует учитывать состояние загрузки и ошибки; нельзя напрямую изменять объект состояния, нужно создавать новое значение. При асинхронном запросе важно не показывать устаревший результат для другого приглашения.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('J-FS-TH-004', '400 означает некорректный запрос, например недопустимое тело; 401 — отсутствующие или недействительные учетные данные; 403 — пользователь аутентифицирован, но действие запрещено; 404 — ресурс не найден. При принятии приглашения без сессии уместен 401, сессия работодателя при попытке действовать от имени кандидата — 403. Если идентификатор приглашения отсутствует — 404. Конкретная политика сокрытия существования чужих записей может возвращать 404 вместо 403.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('J-FS-TH-005', 'Клиентская проверка помогает быстро показать ошибку, но ее можно обойти прямым запросом или изменением браузерного кода. Серверная проверка обязательна и является источником решения. Для диапазона в рублях проверяют, что обе границы — допустимые конечные числа, неотрицательны и минимум не превышает максимум; правила округления и предельные суммы должны быть согласованы с продуктом. Ошибку следует вернуть понятным ответом 400 или 422.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('J-FS-AN-001', 'Эффект запущен один раз, поскольку массив зависимостей пуст. Следует указать specialization, кодировать параметр и обрабатывать состояние ошибки/загрузки; для этого учебного примера достаточно отменять предыдущий запрос при размонтировании или смене фильтра: useEffect(() => { const c = new AbortController(); fetch(''/api/jobs?specialization='' + encodeURIComponent(specialization), {signal:c.signal}).then(r => { if (!r.ok) throw new Error(''HTTP '' + r.status); return r.json(); }).then(setJobs).catch(e => { if (e.name !== ''AbortError'') console.error(e); }); return () => c.abort(); }, [specialization]); В полном интерфейсе ошибку показывают пользователю, а не только в консоли. Типы ответа и начальное состояние также следует определить явно.', 'Эффект запущен один раз, поскольку массив зависимостей пуст. Следует указать specialization, кодировать параметр и обрабатывать состояние ошибки/загрузки; для этого учебного примера достаточно отменять предыдущий запрос при размонтировании или смене фильтра: useEffect(() => { const c = new AbortController(); fetch(''/api/jobs?specialization='' + encodeURIComponent(specialization), {signal:c.signal}).then(r => { if (!r.ok) throw new Error(''HTTP '' + r.status); return r.json(); }).then(setJobs).catch(e => { if (e.name !== ''AbortError'') console.error(e); }); return () => c.abort(); }, [specialization]); В полном интерфейсе ошибку показывают пользователю, а не только в консоли. Типы ответа и начальное состояние также следует определить явно.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('J-FS-AN-002', 'Конкатенация пользовательского значения допускает SQL-инъекцию; ошибки БД не обработаны и могут привести к неконтролируемому отказу запроса. Для SQLite запрос выполняют параметризованно: app.get(''/api/jobs'', async (req, res, next) => { try { const specialization = String(req.query.specialization ?? ''''); if (specialization.length > 80) return res.status(400).json({error:''invalid_specialization''}); const rows = await db.all(''SELECT id, title FROM jobs WHERE specialization = ?'', [specialization]); return res.json(rows); } catch (e) { return next(e); } }); Нужны ограничение формата/длины фильтра и корректный обработчик ошибок Express. Для большого каталога дополнительно применяют пагинацию; пример не должен возвращать все строки без ограничения.', 'Конкатенация пользовательского значения допускает SQL-инъекцию; ошибки БД не обработаны и могут привести к неконтролируемому отказу запроса. Для SQLite запрос выполняют параметризованно: app.get(''/api/jobs'', async (req, res, next) => { try { const specialization = String(req.query.specialization ?? ''''); if (specialization.length > 80) return res.status(400).json({error:''invalid_specialization''}); const rows = await db.all(''SELECT id, title FROM jobs WHERE specialization = ?'', [specialization]); return res.json(rows); } catch (e) { return next(e); } }); Нужны ограничение формата/длины фильтра и корректный обработчик ошибок Express. Для большого каталога дополнительно применяют пагинацию; пример не должен возвращать все строки без ограничения.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('J-FS-PR-001', NULL, NULL, 'type SalaryRange = { min: number; max: number }; type ValidationResult = { ok: true; value: SalaryRange } | { ok: false; errors: string[] }; export function validateSalaryRange(input: unknown): ValidationResult { const errors: string[] = []; if (typeof input !== ''object'' || input === null) return { ok: false, errors: [''Ожидается объект диапазона''] }; const data = input as Record<string, unknown>; const min = data.min; const max = data.max; if (typeof min !== ''number'' || !Number.isFinite(min) || !Number.isInteger(min)) errors.push(''Минимум должен быть целым числом''); if (typeof max !== ''number'' || !Number.isFinite(max) || !Number.isInteger(max)) errors.push(''Максимум должен быть целым числом''); if (typeof min === ''number'' && Number.isFinite(min) && Number.isInteger(min) && min < 0) errors.push(''Минимум не может быть отрицательным''); if (typeof max === ''number'' && Number.isFinite(max) && Number.isInteger(max) && max > 10000000) errors.push(''Максимум превышает допустимую границу''); if (typeof min === ''number'' && typeof max === ''number'' && Number.isFinite(min) && Number.isFinite(max) && min > max) errors.push(''Минимум не может превышать максимум''); if (errors.length) return { ok: false, errors }; return { ok: true, value: { min: min as number, max: max as number } }; } // Пример: validateSalaryRange({min:80000,max:120000}) возвращает {ok:true,value:{min:80000,max:120000}}.', 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('M-FS-TH-001', 'Аутентификация устанавливает, кто пользователь; авторизация определяет, разрешено ли этому пользователю конкретное действие над конкретным ресурсом. Сначала сервер проверяет сессию или токен, затем роль, владение записью и политику доступа. Работодатель может видеть публичные поля профиля, но не контакты до согласия кандидата; одного факта входа или роли employer для раскрытия контактов недостаточно. Проверка выполняется сервером при каждом запросе.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('M-FS-TH-002', 'Проверку статуса и переход нужно выполнять атомарно в транзакции. Например, UPDATE invitations SET status=''accepted'' WHERE id=? AND candidate_id=? AND status=''pending''; затем проверить число затронутых строк. Ровно одна измененная строка означает успешный переход; ноль — приглашение отсутствует, не принадлежит кандидату или уже перешло в другое состояние. Уникальные ограничения и согласованная машина состояний дополняют решение. Не следует сначала читать статус, а затем безусловно обновлять его вне транзакции: оба запроса могут прочитать pending.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('M-FS-TH-003', 'N+1 возникает, когда сначала одним запросом получают список, а затем отдельным запросом загружают связанные данные для каждой записи. Число обращений растет с числом профилей. Проблему выявляют по трассировкам, логам SQL и тестированию с несколькими результатами. Варианты решения: JOIN или пакетная загрузка по списку ID, корректные индексы и пагинация. Не нужно без разбора загружать весь граф связей: выбирают только поля, необходимые экрану, и учитывают дублирование строк при JOIN.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('M-FS-TH-004', 'Следует определить допустимые состояния и переходы, например pending → accepted либо declined, и отдельно описать отмену. Переход проверяется на сервере, а повторный запрос не должен неожиданно менять терминальное состояние. Повторяемые операции можно сделать идемпотентными: повтор возвращает уже достигнутый результат либо понятный конфликт. При создании приглашения помогают ключ идемпотентности и ограничение уникальности, если продукт запрещает дубликаты. Семантика ответов и конфликтов должна быть согласована с клиентом.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('M-FS-TH-005', 'Бизнес-логику следует вынести в функцию или сервис с явными входами и зависимостями, а HTTP-слой оставить ответственным за валидацию, извлечение пользователя и формирование ответа. Предметные ошибки, например NotFound или Conflict, централизованно сопоставляют статусам и безопасным кодам ошибки. Непредвиденные детали не отправляют клиенту; их логируют на сервере с корреляционным идентификатором. Unit-тесты проверяют правила без сети, а интеграционные — маршрутизацию, БД и границы доступа.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('M-FS-AN-001', 'Два запроса могут одновременно прочитать pending и оба вернуть успех. Более того, обновление без candidate_id и условия status может изменить чужую или уже измененную запись. Проверку владения включают в атомарное условное обновление: const result = await db.run("UPDATE invitations SET status=''accepted'' WHERE id=? AND candidate_id=? AND status=''pending''", [req.params.id, req.user.id]); if (result.changes === 1) return res.sendStatus(204); return res.sendStatus(409); При политике сокрытия существования чужих приглашений вместо 409/403 для нулевого результата возвращают одинаковый 404; решение должно быть последовательным и не раскрывать лишние сведения. Обработчик обязан передать исключения middleware ошибок, а наличие аутентифицированного req.user должно гарантировать middleware авторизации. Для SQL-драйвера с транзакциями переход можно дополнительно заключить в транзакцию, особенно если он связан с другими записями или событиями.', 'Два запроса могут одновременно прочитать pending и оба вернуть успех. Более того, обновление без candidate_id и условия status может изменить чужую или уже измененную запись. Проверку владения включают в атомарное условное обновление: const result = await db.run("UPDATE invitations SET status=''accepted'' WHERE id=? AND candidate_id=? AND status=''pending''", [req.params.id, req.user.id]); if (result.changes === 1) return res.sendStatus(204); return res.sendStatus(409); При политике сокрытия существования чужих приглашений вместо 409/403 для нулевого результата возвращают одинаковый 404; решение должно быть последовательным и не раскрывать лишние сведения. Обработчик обязан передать исключения middleware ошибок, а наличие аутентифицированного req.user должно гарантировать middleware авторизации. Для SQL-драйвера с транзакциями переход можно дополнительно заключить в транзакцию, особенно если он связан с другими записями или событиями.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('M-FS-AN-002', 'Нет проверки response.ok, загрузки и ошибки; при быстрой смене jobId старый ответ может прийти позже нового и затереть профиль. Нельзя доверять клиентскому сокрытию контактов: API должно возвращать контакты только после серверной проверки согласия, иначе интерфейс лишь скрывает уже доставленные данные. Один вариант: function Candidate({jobId}:{jobId:string}) { const [state,setState]=useState<{loading:boolean;profile:any;error:string|null}>({loading:true,profile:null,error:null}); useEffect(()=>{ const c=new AbortController(); setState({loading:true,profile:null,error:null}); fetch(''/api/jobs/''+encodeURIComponent(jobId)+''/candidate'',{signal:c.signal}).then(r=>{if(!r.ok) throw new Error(''HTTP ''+r.status); return r.json();}).then(profile=>setState({loading:false,profile,error:null})).catch(e=>{if(e.name!==''AbortError'') setState({loading:false,profile:null,error:''Не удалось загрузить профиль''});}); return ()=>c.abort(); },[jobId]); if(state.loading) return <p>Загрузка</p>; if(state.error) return <p role=''alert''>{state.error}</p>; return <div>{state.profile?.name ?? ''Имя не указано''}</div>; } На практике типизируют DTO вместо any; при 403/404 показывают допустимое продуктом сообщение, не обходят отказ сервера.', 'Нет проверки response.ok, загрузки и ошибки; при быстрой смене jobId старый ответ может прийти позже нового и затереть профиль. Нельзя доверять клиентскому сокрытию контактов: API должно возвращать контакты только после серверной проверки согласия, иначе интерфейс лишь скрывает уже доставленные данные. Один вариант: function Candidate({jobId}:{jobId:string}) { const [state,setState]=useState<{loading:boolean;profile:any;error:string|null}>({loading:true,profile:null,error:null}); useEffect(()=>{ const c=new AbortController(); setState({loading:true,profile:null,error:null}); fetch(''/api/jobs/''+encodeURIComponent(jobId)+''/candidate'',{signal:c.signal}).then(r=>{if(!r.ok) throw new Error(''HTTP ''+r.status); return r.json();}).then(profile=>setState({loading:false,profile,error:null})).catch(e=>{if(e.name!==''AbortError'') setState({loading:false,profile:null,error:''Не удалось загрузить профиль''});}); return ()=>c.abort(); },[jobId]); if(state.loading) return <p>Загрузка</p>; if(state.error) return <p role=''alert''>{state.error}</p>; return <div>{state.profile?.name ?? ''Имя не указано''}</div>; } На практике типизируют DTO вместо any; при 403/404 показывают допустимое продуктом сообщение, не обходят отказ сервера.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('M-FS-PR-001', NULL, NULL, 'import { Router, Request, Response, NextFunction } from ''express''; type AuthRequest = Request & { user: { id: number } }; type RunResult = { changes: number }; type Database = { run(sql: string, params: unknown[]): Promise<RunResult> }; export function invitationRouter(db: Database): Router { const router = Router(); router.post(''/:id/accept'', async (req: AuthRequest, res: Response, next: NextFunction) => { try { const id = Number(req.params.id); if (!Number.isSafeInteger(id) || id <= 0) return res.status(400).json({ error: ''invalid_id'' }); if (!req.user || !Number.isSafeInteger(req.user.id)) return res.status(401).json({ error: ''unauthorized'' }); const result = await db.run("UPDATE invitations SET status=''accepted'' WHERE id=? AND candidate_id=? AND status=''pending''", [id, req.user.id]); if (result.changes !== 1) return res.status(404).json({ error: ''invitation_not_available'' }); return res.sendStatus(204); } catch (error) { return next(error); } }); return router; } // Условный UPDATE атомарно предотвращает повторный переход и проверяет владельца. Единый 404 для нулевого результата не раскрывает, существовала ли чужая запись. При принятой в проекте политике можно различать конфликт и отсутствие, предварительно проверяя их безопасно; это не должно возвращать успех не-владельцу. Тесты должны покрыть pending у владельца, чужой ID, отсутствующий ID, неверный параметр и исключение БД.', 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('S-FS-TH-001', 'Сервер проверяет роль и полномочия работодателя, валидирует вакансию, диапазон зарплаты в рублях и принадлежность доступного профиля; сохраняет приглашение со статусом pending. Кандидат видит приглашение и явно принимает или отклоняет его. Переходы атомарны и допустимы только владельцу приглашения. Контактные поля возвращаются отдельной серверной политикой лишь после подтвержденного согласия; UI-маскирование не является контролем доступа. Важны аудит переходов, защита от повторов, минимизация раскрываемых данных, согласованные ошибки и проверка авторизации на каждом чтении и изменении.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('S-FS-TH-002', 'Практичный вариант — transactional outbox: в одной транзакции записать приглашение и событие outbox; отдельный обработчик отправляет уведомление и помечает событие обработанным. Доставка обычно как минимум однократная, поэтому обработчик и получатель должны выдерживать повторную доставку через устойчивый event ID или ключ идемпотентности. Нужны повторные попытки с ограничением, наблюдаемость и обработка неисправимых ошибок. Нельзя утверждать, что обычная DB-транзакция атомарно охватывает внешний почтовый сервис.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('S-FS-TH-003', 'Сначала определяют востребованные фильтры и порядок сортировки, проверяют планы запросов и создают индексы под реальные сочетания условий, включая внешние ключи. Для стабильной глубокой пагинации предпочтительна cursor/keyset-пагинация по уникальной сортировке; курсор валидируют и не считают средством авторизации. Ограничивают размер страницы, выбирают только необходимые поля и не возвращают контакты до согласия. При более высокой нагрузке рассматривают кэш, поисковый индекс или денормализацию, но задают правила обновления и допустимую задержку согласованности. Решение подтверждают измерениями на репрезентативной нагрузке, а не предположениями.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('S-FS-TH-004', 'Записывают событие перехода с идентификаторами сущности и субъекта, предыдущим и новым статусом, временем и корреляционным идентификатором; допустимые переходы обеспечиваются доменной логикой. Журнал не должен бесконтрольно копировать резюме, телефон, токены или тело запроса. Доступ к аудиту ограничивают, задают срок хранения и правила удаления/обезличивания согласно применимым требованиям организации. События защищают от незаметного изменения организационными средствами и мониторят сбои записи. Сам журнал не заменяет транзакционное обеспечение перехода и не должен выдавать контакты через обычный API.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('S-FS-TH-005', 'На сервере разделяют ожидаемые ошибки предметной области и неожиданные сбои, используют стабильные коды ответа, корреляционные ID и структурированные логи без чувствительных данных. У зависимых компонентов задают тайм-ауты, ограниченные повторы с backoff и jitter только для безопасных операций, а также ограничение параллелизма. Клиент отображает понятное состояние и сохраняет доступность независимых функций; нельзя выдавать устаревшие или приватные данные как свежие. Для кэша явно определяют допустимую давность и очистку после изменения согласия. Наблюдаемость включает метрики отказов и задержек, трассировки и оповещения по пользовательски значимым симптомам.', NULL, NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('S-FS-AN-001', 'Общий кэш ключа профиля опасен: он смешивает контексты работодателей и может выдать контакты без права доступа. Самый безопасный вариант — не кэшировать ответ с контактами; публичную часть можно кэшировать отдельно. Для выдачи приватных полей сервер в одном согласованном чтении проверяет действующее согласие, его связь с кандидатом/приглашением и полномочия текущего работодателя; возвращает минимальный DTO. Если состояние меняется конкурентно, применяют транзакцию с подходящим уровнем изоляции или условную проверку, согласованную с моделью согласия, и определяют момент, после которого отзыв действует. При кэшировании приватного ответа ключ должен учитывать субъект и версию прав, а отзыв обязан инвалидировать записи; без надежной инвалидации кэширование контактов недопустимо. Необходимо также проверять сериализацию, логи и CDN/browser cache headers. Инварианты: чужой работодатель не получает поля; pending и declined не раскрывают контакты; отозванное согласие не используется для новых ответов; неверный статус не расширяет доступ. Тесты — межпользовательские, конкурентные и на повторное использование кэша.', 'Общий кэш ключа профиля опасен: он смешивает контексты работодателей и может выдать контакты без права доступа. Самый безопасный вариант — не кэшировать ответ с контактами; публичную часть можно кэшировать отдельно. Для выдачи приватных полей сервер в одном согласованном чтении проверяет действующее согласие, его связь с кандидатом/приглашением и полномочия текущего работодателя; возвращает минимальный DTO. Если состояние меняется конкурентно, применяют транзакцию с подходящим уровнем изоляции или условную проверку, согласованную с моделью согласия, и определяют момент, после которого отзыв действует. При кэшировании приватного ответа ключ должен учитывать субъект и версию прав, а отзыв обязан инвалидировать записи; без надежной инвалидации кэширование контактов недопустимо. Необходимо также проверять сериализацию, логи и CDN/browser cache headers. Инварианты: чужой работодатель не получает поля; pending и declined не раскрывают контакты; отозванное согласие не используется для новых ответов; неверный статус не расширяет доступ. Тесты — межпользовательские, конкурентные и на повторное использование кэша.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('S-FS-AN-002', 'CSS не защищает данные: контакты уже доставлены браузеру и доступны через DOM, инструменты разработчика, память и сетевой журнал. Согласие должно происходить от кандидата на сервере, а API подбора до него возвращать DTO без контактов. Отдельный серверный endpoint выдачи приватного DTO проверяет пользователя, связь с приглашением и текущий статус; кэширование и логи не должны сохранять приватный ответ небезопасно. На клиенте требуются проверка response.ok, состояние загрузки/ошибки, отмена устаревшего запроса, явные типы и рендеринг по фактически полученным разрешенным полям. Эскиз: type Match={id:string;name:string;specialization:string}; useEffect(()=>{const c=new AbortController(); fetch(''/api/matches'',{signal:c.signal}).then(r=>{if(!r.ok) throw new Error(); return r.json() as Promise<Match[]>;}).then(setResults).catch(e=>{if(e.name!==''AbortError'') setError(''Не удалось загрузить подборку'');}); return ()=>c.abort();},[]); Поля контактов в Match отсутствуют, поэтому компонент физически не может раскрыть их до отдельного авторизованного ответа. Нельзя считать локальный флаг интерфейса доказательством согласия.', 'CSS не защищает данные: контакты уже доставлены браузеру и доступны через DOM, инструменты разработчика, память и сетевой журнал. Согласие должно происходить от кандидата на сервере, а API подбора до него возвращать DTO без контактов. Отдельный серверный endpoint выдачи приватного DTO проверяет пользователя, связь с приглашением и текущий статус; кэширование и логи не должны сохранять приватный ответ небезопасно. На клиенте требуются проверка response.ok, состояние загрузки/ошибки, отмена устаревшего запроса, явные типы и рендеринг по фактически полученным разрешенным полям. Эскиз: type Match={id:string;name:string;specialization:string}; useEffect(()=>{const c=new AbortController(); fetch(''/api/matches'',{signal:c.signal}).then(r=>{if(!r.ok) throw new Error(); return r.json() as Promise<Match[]>;}).then(setResults).catch(e=>{if(e.name!==''AbortError'') setError(''Не удалось загрузить подборку'');}); return ()=>c.abort();},[]); Поля контактов в Match отсутствуют, поэтому компонент физически не может раскрыть их до отдельного авторизованного ответа. Нельзя считать локальный флаг интерфейса доказательством согласия.', NULL, 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
INSERT INTO hackathon_task_answer_keys (task_id, answer, explanation, reference_solution, criteria, max_score) VALUES ('S-FS-PR-001', NULL, NULL, 'type InvitationInput={employerId:number;candidateId:number;specialization:string;salaryMin:number;salaryMax:number}; type Invitation={id:number;employerId:number;candidateId:number;specialization:string;salaryMin:number;salaryMax:number;status:''pending''}; type Tx={findActive(employerId:number,candidateId:number,specialization:string):Promise<Invitation|null>; insert(input:InvitationInput):Promise<Invitation>; addOutbox?(event:unknown):Promise<void>}; type Repository={transaction<T>(work:(tx:Tx)=>Promise<T>):Promise<T>}; class DomainError extends Error { constructor(public code:''INVALID_INPUT''|''DUPLICATE_ACTIVE'',message:string){super(message);this.name=''DomainError'';} } function validId(value:number):boolean{return Number.isSafeInteger(value)&&value>0;} export async function createInvitation(repo:Repository,input:InvitationInput):Promise<Invitation>{ if(!validId(input.employerId)||!validId(input.candidateId)) throw new DomainError(''INVALID_INPUT'',''Некорректный идентификатор''); if(typeof input.specialization!==''string''||input.specialization.trim().length===0||input.specialization.length>80) throw new DomainError(''INVALID_INPUT'',''Некорректная специализация''); const {salaryMin:min,salaryMax:max}=input; if(!Number.isSafeInteger(min)||!Number.isSafeInteger(max)||min<0||max<min||max>10000000) throw new DomainError(''INVALID_INPUT'',''Некорректный диапазон зарплаты''); const normalized={...input,specialization:input.specialization.trim()}; return repo.transaction(async tx=>{ const existing=await tx.findActive(normalized.employerId,normalized.candidateId,normalized.specialization); if(existing) throw new DomainError(''DUPLICATE_ACTIVE'',''Активное приглашение уже существует''); const invitation=await tx.insert(normalized); if(tx.addOutbox) await tx.addOutbox({eventId:''generated-by-repository'',type:''InvitationCreated'',invitationId:invitation.id}); return invitation; }); } // В рабочей системе защита от параллельных дубликатов не может полагаться только на findActive: нужна уникальность в БД, например частичный уникальный индекс для активных статусов, либо сериализуемая/блокирующая стратегия. Нарушение уникальности преобразуют в DUPLICATE_ACTIVE. Все операции вставки и outbox выполняют в одной транзакции. Если интерфейс outbox отсутствует, уведомление не отправляют внутри этой функции; репозиторий расширяют атомарной записью события. HTTP-слой отдельно сверяет employerId с аутентифицированным субъектом, не доверяя ID из тела, и преобразует DomainError в безопасный ответ.', 'Ручная оценка работодателем: корректность, полнота, качество объяснения/кода. Точная шкала не задана в исходном документе.', 10) ON CONFLICT (task_id) DO UPDATE SET answer=EXCLUDED.answer, explanation=EXCLUDED.explanation, reference_solution=EXCLUDED.reference_solution, criteria=EXCLUDED.criteria, max_score=EXCLUDED.max_score;
COMMIT;
